export const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
export const rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
export const PET_RARITIES=[{id:'common',name:'普通',weight:700,factor:1},{id:'rare',name:'稀有',weight:250,factor:1.06},{id:'uncommon',name:'罕見',weight:45,factor:1.1236},{id:'legendary',name:'傳說',weight:4,factor:1.26405},{id:'mythic',name:'神話',weight:1,factor:1.42205625}];
export const PET_EVOLUTIONS=[{level:20,id:'essence_1',count:8,range:'Lv.1–20',mutation:{common:.12,rare:.055,uncommon:.012,legendary:.003}},{level:40,id:'essence_2',count:12,range:'Lv.21–40',mutation:{common:.15,rare:.07,uncommon:.016,legendary:.004}},{level:60,id:'essence_3',count:16,range:'Lv.41–60',mutation:{common:.18,rare:.085,uncommon:.02,legendary:.005}},{level:80,id:'essence_4',count:20,range:'Lv.61–99',mutation:{common:.2,rare:.1,uncommon:.025,legendary:.006}}];
export const petRarity=pet=>PET_RARITIES.find(r=>r.id===pet.rarity)||PET_RARITIES[0];
for(const step of PET_EVOLUTIONS)step.mutation={...MYTHIC_MUTATION};
export const nextPetEvolution=pet=>PET_EVOLUTIONS[pet.evolution||0]||null;
export function makePet(species){const s=SPECIES[species],rarityId=captureQuality(),rarity=PET_RARITIES.find(r=>r.id===rarityId);const pet={id:globalThis.crypto?.randomUUID?.()||`pet-${Date.now()}-${rand(1000,9999)}`,species,nickname:s.name,level:1,xp:0,rarity:rarity.id,evolution:0,iv:{hp:rand(0,5),atk:rand(0,4),def:rand(0,3),matk:rand(0,4),sp:rand(0,4),aspd:rand(0,3)},hp:s.baseHp,sp:45,active:false,gear:{head:null,body:null,shoes:null}};pet.nickname=petForm(pet)||s.name;const stats=petStats(pet);pet.hp=stats.hp;pet.sp=stats.sp;return pet;}
export function petStats(pet){const fusion=fusedPair(pet),s=SPECIES[fusion?({attack:'fang',magic:'wisp',defense:'shell',support:'sprout'})[companionRole(pet)]:pet.species],level=pet.level,iv=pet.iv||{},gear=Object.values(pet.gear||{}).filter(item=>!item||(item.level||1)<=level),bonus=type=>gear.reduce((n,item)=>n+(item?.affixes?.[type]||0),0),quality=petRarity(pet).factor,evolution=clamp(pet.evolution||0,0,4),role=s.role;const evolvePower=1+evolution*.065,growth=s.growth;const scaled=(base,perLevel,individual=0)=>Math.round(base+(level-1)*perLevel+individual);const hp=scaled(s.baseHp,growth.hp*(role==='defense'?1.8:2.4),(iv.hp||0)*2);const magic=role==='magic',support=role==='support',defense=role==='defense',attack=role==='attack';const atk=scaled(s.atk*(magic?.45:1),growth.atk*(attack?1.6:magic?.45:defense?.65:.7),iv.atk||0);const matk=scaled(magic?19:support?12:attack?5:4,magic?growth.atk*1.75:support?2.7:attack?1.4:1.2,iv.matk||0);const stats={hp:Math.round((hp*(defense?evolvePower:1+evolution*.035)+bonus('hp'))*(1+bonus('hpPct')/100)),sp:Math.round((45+(level-1)*(magic?8:support?9:4)+(iv.sp||0)*3)*(magic||support?evolvePower:1+evolution*.025)+bonus('sp')),atk:Math.round(atk*(attack?evolvePower:1+evolution*.025)+bonus('atk')+bonus('STR')*2),matk:Math.round(matk*(magic?evolvePower:1+evolution*.025)+bonus('matk')+bonus('INT')*2),def:Math.round((s.def+(level-1)*growth.def*(defense?1.25:1.8)+(iv.def||0))*(defense?evolvePower:1+evolution*.02)+bonus('def')+bonus('VIT')),mdef:Math.round((s.def+(level-1)*(magic?2.2:defense?2.5:1)+(iv.def||0))*(defense?evolvePower:1+evolution*.025)+bonus('mdef')+bonus('INT')),aspd:Math.round(clamp(200-50*s.speed/1000+level*(attack?.17:magic?.12:defense?.075:.095)+(iv.aspd||0)*.4+evolution*(attack?1.5:.7)+bonus('aspd')+bonus('AGI')*.1,130,193)*10)/10,hit:Math.round(85+level*(attack?2.5:magic?2.1:1.7)+(iv.atk||0)*2+evolution*3+bonus('hit')+bonus('DEX')),flee:Math.round(65+level*(support?2.5:attack?2.1:1.7)+(iv.def||0)*2+evolution*3+bonus('flee')+bonus('AGI')),crit:Math.min(60,1+level*(attack?.13:.055)+evolution*.6+bonus('crit')),speed:s.speed};stats.flee=Math.round(stats.flee*(1+bonus('fleePct')/100));stats.damageReduction=Math.min(40,bonus('damageReduction'));stats.aspdPct=bonus('aspdPct');stats.ignoreDef=Math.min(60,bonus('ignoreDef'));stats.crit=Math.min(100,stats.crit);stats.critDmg=140+bonus('critDmg');stats.level=level;stats.quality=quality;for(const key of ['hp','sp','atk','matk','def','mdef'])stats[key]=Math.round(stats[key]*quality);if(pet.ascended)for(const key of ['hp','sp','atk','matk','def','mdef'])stats[key]=Math.round(stats[key]*1.15);if(fusion){if(['magic','support'].includes(role))stats.matk+=Math.round((bonus('atk')+bonus('STR')*2)*quality*1.15*.8);else if(role==='attack')stats.atk+=Math.round((bonus('matk')+bonus('INT')*2)*quality*1.15*.8);for(const key of ['hp'])stats[key]=Math.round(stats[key]*fusion.hp);for(const key of ['def','mdef'])stats[key]=Math.round(stats[key]*fusion.def);for(const key of ['atk','matk'])stats[key]=Math.round(stats[key]*fusion.attack);}
stats.healPower=Math.round((support?stats.matk:magic?stats.matk:defense?stats.def*.7+stats.hp*.02:stats.atk*.65)*(support?evolvePower:1));return stats;}
export {PET_SLOTS};
